window.HYPOTHESES = {"published_at": "2026-09-09T22:58:11.995823+00:00", "experiment": "APOE4 vs APOE3 / mock microglia", "discovery": "RNA and protein", "evaluation_features": 618, "baseline": {"balanced_direction_accuracy": 0.5, "centered_cosine_similarity": 0.0, "cosine_similarity": 0.5446567723274521, "direction_accuracy": 0.8268608414239482, "hypothesis_id": "constant_positive_one", "mean_absolute_error": 0.7320097087378641, "by_modality": {"lipid_abundance": {"balanced_direction_accuracy": 0.5, "centered_cosine_similarity": 0.0, "cosine_similarity": 0.5446567723274521, "direction_accuracy": 0.8268608414239482, "mean_absolute_error": 0.7320097087378641, "n_features": 618}}}, "cohorts": [{"id": "opus-original", "label": "Opus / original", "count": 996, "best": 0.5391946857970239, "mean": 0.27588171328191674, "selected_count": 4}, {"id": "sonnet-original", "label": "Sonnet / original", "count": 10, "best": 0.3101171980232298, "mean": 0.11734671255708165, "selected_count": 0}, {"id": "opus-evidence-v2", "label": "Opus / evidence-v2", "count": 358, "best": 0.5224560945546165, "mean": 0.32747311982070454, "selected_count": 6}, {"id": "astra-forecast-v3", "label": "Astra / original", "count": 20, "best": 0.31591653415995535, "mean": -0.009822704097367563, "selected_count": 0}, {"id": "astra-evidence-v2", "label": "Astra / evidence-v2", "count": 38, "best": 0.3895856673297374, "mean": 0.15215022912407322, "selected_count": 0}, {"id": "sonnet-evidence-v2", "label": "Sonnet / evidence-v2", "count": 10, "best": 0.424771974705316, "mean": 0.28698202653700305, "selected_count": 0}], "hypotheses": [{"id": "opus-original-b07-hyp_189", "cohort": "opus-original", "batch": 7, "hypothesis": {"hypothesis_id": "hyp_189", "title": "APOE4 microglia amplify lysosomal hydrolase/v-ATPase transcription while relatively downgrading late-fusion SNAREs, making cargo delivery into the lysosome the catabolic bottleneck", "claim": "In isogenic mock-treated iPSC-derived microglia, the APOE4 genotype is associated with a coordinated transcript increase in acid hydrolases, v-ATPase subunits and TFEB together with a relative decrease in the SNARE machinery that executes late-endosome/autophagosome-to-lysosome fusion (STX17, STX16, VAMP2, STXBP5). We hypothesise that the rate-limiting step in APOE4 microglia is delivery of internalised and autophagic lipid cargo into the acidified hydrolase-rich compartment, not hydrolase supply or particle uptake, so lipid substrate dwells upstream of the lysosome while SREBP-linked lipogenic transcripts remain high; uptake and phagocytic-receptor machinery is not reduced, so this is a post-internalisation handling defect rather than a phagocytic-cup/actin defect.", "mechanism_steps": ["APOE4 cells show a coherent above-background elevation of lysosomal hydrolase and v-ATPase transcripts (GAA, GBA, HEXA, SMPD1, CTSB, CTSD, CTSK, ATP6V1A, ATP6V1H) plus TFEB; we infer, but did not measure, increased lysosomal biogenesis drive and hydrolase protein synthesis.", "In the same comparison, transcripts encoding the fusion step that delivers late endosomes/autophagosomes to lysosomes (STX17, STX16, VAMP2, STXBP5) fall in the lowest ~13% of this differential-expression list, while recycling-route SNAREs (VAMP3, STX12) do not; we infer a relative shift of membrane traffic away from degradative fusion toward recycling.", "The proposed bottleneck is therefore the fusion/delivery step: catabolic flux through the lysosome is limited by cargo access to hydrolases rather than by hydrolase abundance (flux, localisation and fusion rate are inferred, not measured here).", "Internalised lipid-rich cargo and autophagic membrane consequently dwell in pre-lysosomal compartments and neutral-lipid stores; sterol liberated from such cargo does not reach the ER sensing pool, so SREBP-linked lipogenic/sterol transcripts (SREBF1, SREBF2, INSIG1, SCD, DHCR24, DHCR7, LSS, DGAT1) stay high and add further lipid load.", "Hydrolase output that cannot engage cargo is predicted to redistribute between proform, mature and secreted pools; 2-D protein spots whose candidate lists include CTSB or CTSD change in opposite directions (spots 055/057/053 up, 058/067/069 down), which is consistent with, but does not identify, such redistribution.", "Because phagocytic-receptor and ARP2/3 transcripts (TREM2, MERTK, SCARB1, ITGB1, ITGAX, C1QA-C, ARPC1B, ARPC4, ARPC5) are not reduced relative to the global shift, the net APOE4 phenotype is predicted to be normal-or-increased uptake with slowed post-uptake degradation and lipid retention."], "assumptions": ["The RNA effects are reported log fold changes of unspecified base from a pre-selected differential-expression list (all |effect| \u003e 1), so only ranks relative to the strong global positive shift (median +1.46) are interpreted, not absolute magnitudes.", "Transcript changes for SNARE and hydrolase genes are assumed to track the corresponding protein and complex abundance; neither protein was measured for STX17, STX16, VAMP2 or STXBP5 in the supplied data.", "Protein spots have multiple candidate genes and are treated as ambiguous, non-identifying evidence only.", "Lysosomal pH, fusion rate, cargo flux, lipid droplet content and cholesteryl esters were not measured; all flux, localisation and causal statements are inferred.", "Astrocyte co-culture and the 10X Flex pseudobulk-style comparison with unstated replicate number could contribute composition effects that the supplied data cannot exclude; causality is not established."], "falsifiable_predictions": ["Pulse-chase with fluorescent myelin or pHrodo/DQ-BSA cargo: APOE4 microglia should internalise at least as much as APOE3 at early times (\u003c=30 min) but show reduced cargo-LAMP1 colocalisation and slower DQ-BSA dequenching later; if APOE4 instead internalises less at early times, the uptake/actin-cytoskeleton alternative is supported and this mechanism is weakened.", "Restoring STX17 (and/or STX16) expression in APOE4 microglia should increase cargo-lysosome fusion and lower BODIPY neutral-lipid load without raising hydrolase transcripts; no reduction in lipid load despite verified restoration would weaken the mechanism.", "Knockdown of STX17 in APOE3 microglia should phenocopy APOE4 lipid retention and slowed cargo degradation; failure to phenocopy weakens the bottleneck assignment.", "SREBP or SCD inhibition should reduce droplet load but should NOT normalise cargo-to-lysosome delivery kinetics; if it normalises delivery, lipogenic supply rather than fusion is the primary bottleneck.", "Immunoblot/immunostain in APOE4 versus APOE3 should show reduced STX17 and STX16 protein with unchanged or increased mature CTSB/CTSD and v-ATPase subunits; unchanged STX17/STX16 protein, or reduced mature cathepsins, would weaken the core premise.", "Bafilomycin A1 or hydrolase inhibition should increase lipid retention proportionally less in APOE4 than in APOE3, because APOE4 degradative flux is already delivery-limited; an equal or larger APOE4 response would weaken the mechanism."]}, "score": {"hypothesis_id": "hyp_189", "cosine_similarity": 0.5391946857970239, "centered_cosine_similarity": 0.23482078475066162, "direction_accuracy": 0.6148867313915858, "balanced_direction_accuracy": 0.37084148727984345, "mean_absolute_error": 0.5231197411003237, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.5391946857970239, "centered_cosine_similarity": 0.23482078475066162, "direction_accuracy": 0.6148867313915858, "balanced_direction_accuracy": 0.37084148727984345, "mean_absolute_error": 0.5231197411003237}}}, "cost_usd": 1.80450075, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 1, "global_rank": 1}, {"id": "opus-original-b02-hyp_073", "cohort": "opus-original", "batch": 2, "hypothesis": {"hypothesis_id": "hyp_073", "title": "APOE4 microglia bias carbon into a mitochondrial TCA/citrate-export node that feeds SREBF1-driven neutral-lipid esterification, with lysosomal hydrolase transcription rising only as a secondary response", "claim": "Under mock conditions, isogenic APOE4 iPSC-microglia differ from APOE3 primarily by a coherent transcriptional expansion of mitochondrial pyruvate/anaplerotic entry, TCA-cycle enzymes and mitochondrial carriers that outstrips the global upward shift of this differential-expression list, while glycolytic commitment steps are not co-induced. We propose the rate-limiting node is mitochondrial citrate/malate export (SLC25A1-SLC25A11 exchange), which supplies cytosolic acetyl-CoA for an SREBF1-associated lipogenic and sterol-esterification program (SCD, DGAT1, SOAT1, ACAT2, DHCR24), producing neutral-lipid accumulation. Increased lysosomal hydrolase and V-ATPase mRNA (including TFEB) is interpreted as a downstream CLEAR-type response to lipid load rather than the primary defect, because it is weaker than the mitochondrial signal, internally discordant (CTSS, IDS decreased) and not corroborated at the protein-spot level. Causality is not established by these data.", "mechanism_steps": ["Step 1 (measured RNA, inferred flux): APOE4 microglia show higher mRNA for mitochondrial substrate entry and anaplerosis (MPC2, GLUD1, GLS, NNT). We infer, but did not measure, increased pyruvate and glutamate-derived carbon entry into the matrix.", "Step 2 (measured RNA, inferred capacity): TCA-cycle enzyme transcripts (ACO2, OGDH, DLD, IDH3G, MDH1, GOT1) are coordinately elevated well above the list-wide shift, implying increased citrate/malate cycling capacity; enzyme activity and metabolite pools were not measured.", "Step 3 (measured RNA, inferred flux partitioning): electron-transport subunit transcripts (NDUFA5, NDUFS7, UQCRC2, COX7A2, ATP5ME and ~35 further subunits) rise while committed glycolytic steps do not (HK2 and PFKP decreased), consistent with an oxidative rather than glycolytic bias; oxygen consumption was not measured.", "Step 4 (proposed bottleneck, measured RNA only): the exit of carbon from the matrix as citrate via SLC25A1, balanced by SLC25A11 malate/2-oxoglutarate exchange and SLC25A5 adenine-nucleotide exchange, is the step we propose limits how much of this oxidative carbon is diverted to cytosolic acetyl-CoA; ACSS2 provides a parallel acetate-derived route. Cytosolic acetyl-CoA and citrate pools are unmeasured and must not be treated as observed.", "Step 5 (measured RNA, inferred activity): the cytosolic acetyl-CoA supply supports an SREBF1-associated program (SCD, DGAT1, ACAT2, SOAT1, DHCR24, INSIG1, LDLR, MYLIP), which we infer channels fatty acid and sterol into triacylglycerol and cholesteryl ester; SREBP processing, localization and lipid species were not measured.", "Step 6 (secondary, partly discordant): the resulting neutral-lipid and membrane load engages a CLEAR-type transcriptional response (TFEB up; GAA, CTSB, CTSD, and V-ATPase subunit mRNA up), which we treat as compensatory rather than causal because cathepsin- and V-ATPase-containing protein spots move in both directions and CTSS and IDS mRNA are decreased."], "assumptions": ["The supplied RNA rows are a pre-filtered differential-expression list (every |effect| exceeds 1) with a strong list-wide positive shift, so only within-list rank enrichment, not absolute direction, is interpreted; the logarithm base and pseudocount are unspecified and effects are treated as ordinal.", "Coordinated transcript increases in a nuclear-encoded TCA/ETC/carrier module reflect increased pathway capacity rather than a normalization, ambient-RNA or cell-quality artifact that preferentially inflates highly expressed housekeeping transcripts.", "Transcript abundance is used as a proxy for enzyme abundance and for flux at steps where no protein, metabolite, flux or localization measurement is supplied (all of Steps 1-5).", "Protein spots contain 3-6 candidate genes each and show frequent keratin and actin contamination, so no spot is assigned to a unique protein; spots are used only as weak, non-identifying corroboration or counter-evidence.", "Microglia were co-cultured with astrocytes, so genotype-driven astrocyte lipid or APOE secretion could contribute to the microglial state; cell-type deconvolution and any lipid, oxygen-consumption or tracer measurement are absent from the supplied data.", "SREBF1 target induction is assumed to reflect increased SREBP-1 transcriptional activity rather than only compensatory feedback to sterol depletion."], "falsifiable_predictions": ["Discriminating perturbation: in APOE4 microglia, SLC25A1 knockdown or citrate-carrier inhibition (CTPI-2) should lower neutral-lipid droplet content and de novo 13C-glucose incorporation into C16:0/C18:1 toward APOE3 levels, while leaving ETC subunit transcript elevation largely intact. If LD content and glucose-derived fatty-acid labelling are unchanged by SLC25A1 loss, the proposed citrate-export bottleneck is wrong.", "13C-glucose and 13C-glutamine tracing should show higher M+2 citrate enrichment and a higher glucose-derived fraction of cytosolic fatty acid in APOE4 than APOE3 under mock. Equal or lower enrichment in APOE4 would weaken Steps 1-4.", "Extracellular flux analysis should show higher basal and maximal oxygen consumption in APOE4 without a matched increase in glycolytic rate. A glycolytic rather than oxidative shift, or no OCR difference, would weaken Step 3.", "Discriminating against the lysosomal-capacity alternative: acute lysosomal inhibition (bafilomycin A1 or a pan-cathepsin inhibitor) should increase lipid droplets in both genotypes but should not abolish the APOE4-over-APOE3 excess, whereas DGAT1 or SCD inhibition should collapse that excess. If the APOE4 excess disappears only with lysosomal manipulation, the primary bottleneck is endolysosomal, not the citrate-export node.", "Bulk cathepsin B/D and beta-glucocerebrosidase enzymatic activity and mature-cathepsin immunoblots should not be uniformly higher in APOE4 despite elevated transcripts, matching the bidirectional cathepsin-containing spots. Uniformly higher hydrolase activity plus intact substrate clearance would argue the CLEAR response is sufficient and would weaken Step 6.", "TFEB nuclear translocation should be a consequence of lipid load: pharmacological blockade of neutral-lipid esterification should reduce TFEB target transcripts in APOE4. Persistent TFEB target induction after lipid-storage blockade would place the lysosomal program upstream and falsify the ordering in Step 6."]}, "score": {"hypothesis_id": "hyp_073", "cosine_similarity": 0.5279950098961133, "centered_cosine_similarity": 0.302168459557284, "direction_accuracy": 0.5, "balanced_direction_accuracy": 0.3013698630136986, "mean_absolute_error": 0.512948220064725, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.5279950098961133, "centered_cosine_similarity": 0.302168459557284, "direction_accuracy": 0.5, "balanced_direction_accuracy": 0.3013698630136986, "mean_absolute_error": 0.512948220064725}}}, "cost_usd": 1.883722, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 2, "global_rank": 2}, {"id": "opus-evidence-v2-b03-hyp_126", "cohort": "opus-evidence-v2", "batch": 3, "hypothesis": {"hypothesis_id": "hyp_126", "title": "APOE4 microglia run a lipid-uptake plus lysosome-expansion state whose sterol output fails to reach the ER sensor, sustaining SREBP-driven synthesis and storage (routing mismatch, not interferon signaling)", "claim": "Under mock treatment, APOE4 (vs isogenic APOE3) iPSC-derived microglia occupy a coordinated lipid-handling cell state in which transcripts for lipoprotein/lipid capture, endolysosomal delivery and TFEB/MITF-type lysosomal biogenesis are jointly elevated, yet SREBP1/SREBP2 target transcripts remain elevated rather than suppressed; the most parsimonious mechanistic reading is that lysosomally delivered sterol/lipid is preferentially routed into lysosomal and esterified/stored pools instead of the ER regulatory sterol pool, so the ER sensor continues to read 'sterol-poor' while oxysterol/LXR-type outputs rise, producing a futile uptake-plus-synthesis cycle and a lipid-laden lysosomal state with a low-grade chemokine tone. Type I interferon signaling is not supported as the driver and is rejected as the primary explanation. Causality is not established: all evidence is steady-state transcript abundance from a selected differential-expression list plus ambiguous protein spots; no sterol pool, flux, lysosomal pH, hydrolase activity or TFEB localization was measured.", "mechanism_steps": ["STEP 1 (measured abundance): APOE4 microglia show elevated transcripts for lipoprotein/lipid capture and handling receptors and carriers (gene:SCARB1 +8.22, gene:CD36 +1.38, gene:TREM2 +1.28, gene:COLEC12 +1.53, gene:STAB1 +1.13, gene:LDLR +1.50, gene:APOE +1.24, gene:PLTP +1.06, gene:ABCA7 +2.14), consistent with (but not proof of) increased lipid influx into the endocytic route.", "STEP 2 (measured abundance, inferred capacity): endolysosomal delivery and a TFEB/MITF-type lysosomal biogenesis program are co-elevated (gene:RAB7A +2.65, gene:VPS26A +4.86, gene:SNX3 +3.95, gene:CHMP4B +3.82, gene:DNM2 +5.82; gene:TFEB +2.38, gene:MITF +1.03, gene:LAMP1 +1.38, gene:SCARB2 +1.06, gene:CLN3 +1.17, gene:SLC38A7 +7.46, gene:ATP6V1H +6.88, gene:ATP6V1A +4.23, gene:ATP6V0C +3.51, gene:GAA +9.96, gene:GBA +6.71, gene:HEXA +5.68, gene:CTSB +5.52, gene:CTSK +7.36, gene:SMPD1 +5.63, gene:NAGLU +5.91, gene:CTSD +2.86), i.e. expanded degradative-compartment transcript supply rather than a transcriptional lysosomal deficit.", "STEP 3 (inferred routing, decisive step): despite steps 1-2, ER sterol-sensing output stays in the 'sterol-poor' mode - SREBP factors and their sterol/fatty-acid synthesis targets are up (gene:SREBF1 +4.67, gene:SREBF2 +1.06, gene:SCD +4.17, gene:HMGCS1 +1.08, gene:LSS +2.27, gene:DHCR7 +2.71, gene:DHCR24 +3.69, gene:EBP +1.34, gene:ACAT2 +2.04, gene:INSIG1 +1.87, gene:LDLR +1.50), while oxysterol-generating and LXR-type outputs rise in parallel (gene:CH25H +1.62, gene:CYP27A1 +1.49, gene:MYLIP +1.28, gene:ABCA7 +2.14, gene:APOE +1.24). Simultaneous 'need more sterol' and 'sterol present elsewhere' signals indicate compartment mismatch rather than global sterol excess or global sterol shortage.", "STEP 4 (inferred flux/storage): incoming and newly made lipid is biased toward esterified and membrane-storage pools instead of the ER regulatory pool (gene:SOAT1 +1.25, gene:DGAT1 +1.72, gene:MGLL +4.00, gene:AGPAT2 +6.29, gene:LPCAT1 +3.07, gene:CHPT1 +2.91, gene:CIDEB +1.06) with sphingolipid/glycosphingolipid turnover transcripts also raised (gene:SMPD1 +5.63, gene:GBA +6.71, gene:GBA2 +2.63, gene:ST3GAL5 +2.17, gene:CERS6 +1.06).", "STEP 5 (predicted state in the measured mock condition): the resulting state is a futile cycle - continued uptake plus continued synthesis into lysosome/droplet pools - so APOE4 microglia should already carry more lysosomal and esterified neutral lipid than APOE3 at day 30, with lysosomal expansion acting as partial, still-incomplete compensation (a defect in ER sterol delivery, not necessarily a defect in bulk hydrolysis).", "STEP 6 (downstream, secondary): the lipid-laden endolysosomal state is accompanied by a modest chemokine/inflammasome-priming tone (gene:CXCL8 +3.11, gene:CXCL1 +1.59, gene:CXCL2 +1.65, gene:CXCL3 +1.56, gene:CCL2 +2.12, gene:NLRP3 +1.09, gene:PYCARD +2.43, gene:IL18 +1.46, gene:MYD88 +2.34, gene:TLR2 +1.20) that is NOT accompanied by a coherent type I interferon program (only gene:IRF8 +1.39, gene:TMEM173 +1.22, gene:CD74 +3.84, gene:CIITA +1.50 represented; gene:IRF2 -1.17; no ISG15/MX/OAS/IFIT/STAT1/STAT2/IRF7/GBP rows supplied), so interferon signaling is rejected as the driver and the chemokine tone is placed downstream, not upstream."], "assumptions": ["The 2212 supplied RNA rows are a pre-selected differential-expression list (all adjusted p \u003c 0.05; 77.1% positive), so program coherence was judged against that biased background, not against 50/50; genes absent from the list (e.g. NPC1, ABCA1, HMGCR, SQLE, MCOLN1, TNF, IL1B, STAT1, MX1) are unknown, not unchanged.", "The RNA logarithm base is unspecified and effect magnitudes are unusually large; only signs and relative ranks are treated as informative, and no cross-modality magnitude comparison with the log2 protein spots is made.", "Marker membership was pre-specified from canonical pathway knowledge (unverified background knowledge; literature/database retrieval was disabled) and queried before effects were read; represented-vs-queried counts are reported and no member was dropped to make directions agree.", "Transcript abundance is assumed to correlate with, but not to demonstrate, protein level, enzymatic activity, TFEB nuclear localization, lysosomal acidification or lipid flux; every activity, routing and flux statement is inferred, not observed.", "Protein spots are multi-candidate (3-6 candidate genes each; ACTB appears in 26 spots), so no spot is treated as identifying an individual protein; spots are used only for compatibility/contradiction.", "Astrocyte co-culture supplies exogenous lipoproteins, so a lipid-uptake-driven state is plausible in this specific culture; the mechanism is stated for the mock (unchallenged) condition, and any additional fragility under lipid or inflammatory challenge is a predicted future-challenge phenotype, not an observed one."], "falsifiable_predictions": ["PROSPECTIVE DISCRIMINATOR (routing mismatch vs matched high throughput): acute sterol loading of mock APOE4 and APOE3 microglia (LDL or cholesterol/methyl-beta-cyclodextrin, 4-8 h) should suppress SREBP2 targets (HMGCS1, LSS, DHCR7, LDLR) markedly less in APOE4 than in APOE3, while total and lysosomal cholesterol rises at least as much in APOE4. If APOE4 shows normal or stronger SREBP2 feedback suppression, the routing-mismatch step (STEP 3) is falsified and 'successful high-throughput adaptation' is favored.", "PROSPECTIVE: filipin/LipidTOX plus LAMP1 imaging and lipidomics in mock day-30 APOE4 vs APOE3 should show increased lysosomal free cholesterol, cholesteryl ester and glycosphingolipid content with equal-or-greater LAMP1+ compartment volume. Absence of lipid accumulation despite the transcript pattern would weaken the whole mechanism.", "PROSPECTIVE RESCUE: relieving lysosomal sterol export (2-hydroxypropyl-beta-cyclodextrin) or blocking esterification (SOAT1/ACAT inhibitor, e.g. avasimibe) should lower SREBP2-target transcripts and reduce the chemokine tone (CXCL8, CCL2) in APOE4 toward APOE3 without lowering LAMP1/hydrolase transcripts first. No normalization of SREBP2 targets would weaken STEP 3-4.", "PROSPECTIVE ACTIVITY TEST: per-cell GBA, HEXA and GAA enzymatic activity and BODIPY-LDL degradation rate should be equal or higher in APOE4 (expanded capacity), while an ER-targeted sterol biosensor reads lower in APOE4. Finding reduced hydrolase activity instead would replace 'routing mismatch' with a genuine lysosomal catabolic deficit.", "PROSPECTIVE NEGATIVE CONTROL for the rejected focus: JAK1/2 inhibition or IFNAR blockade in mock culture should leave the lysosomal, SREBP and lipid-storage transcript differences essentially intact. If JAK/IFNAR blockade abolishes them, an interferon-driven explanation would supersede this mechanism.", "PROSPECTIVE (protein level, spot ambiguity resolved): targeted immunoblot/MS of CTSB, CTSD, HEXB and ATP6V1E1 should show APOE4 increases consistent with the transcripts; persistent decreases (as some spots such as protein_spot:067, protein_spot:069, protein_spot:064 would allow) would indicate post-transcriptional loss of lysosomal protein and weaken STEP 2."]}, "score": {"hypothesis_id": "hyp_126", "cosine_similarity": 0.5224560945546165, "centered_cosine_similarity": 0.2870096593090623, "direction_accuracy": 0.5792880258899676, "balanced_direction_accuracy": 0.43254070819333157, "mean_absolute_error": 0.5185728155339806, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.5224560945546165, "centered_cosine_similarity": 0.2870096593090623, "direction_accuracy": 0.5792880258899676, "balanced_direction_accuracy": 0.43254070819333157, "mean_absolute_error": 0.5185728155339806}}}, "cost_usd": 2.0461345, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 1, "global_rank": 3}, {"id": "opus-evidence-v2-b04-hyp_199", "cohort": "opus-evidence-v2", "batch": 4, "hypothesis": {"hypothesis_id": "hyp_199", "title": "APOE4 microglia occupy a TFEB-associated endolysosomal lipid-processing state in which sterol is routed to lysosomal/storage compartments while ER sterol sensing stays de-repressed, supported by expanded mitochondrial oxidative machinery", "claim": "Under mock treatment, isogenic APOE4 iPSC-microglia (co-cultured with astrocytes, day 30) differ from APOE3 mainly by a coordinated cell-state change of the lipid-handling axis, not by a phagocytic or actin-cytoskeletal defect: transcripts for lipid/lipoprotein uptake, TFEB-type lysosomal biogenesis (v-ATPase plus hydrolases), endosomal sorting, sterol synthesis/esterification and oxysterol disposal, and for oxidative phosphorylation with mitochondrial antioxidants, are jointly higher in APOE4. The pattern is best explained by altered intracellular routing of sterol/lipid into an expanded acidic-storage compartment, so that the ER-accessible sterol pool that would switch off SREBP targets remains low while cargo continues to be imported and oxidized. This is a measured-state difference in transcript abundance and inferred routing; increased degradative or oxidative flux is not measured, and a rate-limiting defect is not claimed for the mock condition.", "mechanism_steps": ["APOE4 microglia show higher transcript levels for lipid/lipoprotein and debris receptors and for APOE-pathway components themselves (gene:SCARB1 +8.22, gene:LDLR +1.50, gene:CD36 +1.38, gene:TREM2 +1.28, gene:ABCA7 +2.14, gene:APOE +1.24; effects are reported log fold change, base unspecified), which we interpret as increased capacity, not measured uptake, for delivering lipid cargo into the endocytic route.", "Cargo is directed into an enlarged endolysosomal compartment: a TFEB/CLEAR-type coordinate induction is present (gene:TFEB +2.38, gene:MITF +1.03) together with 8/8 represented v-ATPase subunits up (gene:ATP6V1H +6.88, gene:ATP6V1A +4.23, gene:ATP6V0C +3.51) and acid hydrolases (gene:GAA +10.0, gene:CTSK +7.36, gene:GBA +6.71, gene:NAGLU +5.91, gene:HEXA +5.68, gene:CTSB +5.52, gene:CTSD +2.86), plus endosomal sorting and maturation machinery (gene:VPS26A +4.86, gene:VPS35L +3.54, gene:SNX3 +3.95, gene:CHMP4B +3.82, gene:RAB7A +2.65, gene:PIK3C3 +2.92, gene:AP5M1 +9.8).", "Sterol that enters this route is preferentially esterified/stored and converted to oxysterols rather than raising the ER regulatory sterol pool (gene:SOAT1 +1.25, gene:DGAT1 +1.72, gene:CH25H +1.62, gene:CYP27A1 +1.49, gene:MYLIP +1.28, gene:ABCA7 +2.14); the ER-accessible pool itself was not measured and this step is inferred.", "Because ER sterol sensing continues to read low, the SREBP-target arm stays induced despite the elevated uptake machinery, producing a self-sustaining import/synthesis cycle (gene:SREBF1 +4.67, gene:SREBF2 +1.06, gene:INSIG1 +1.87, gene:LDLR +1.50, gene:HMGCS1 +1.08, gene:LSS +2.27, gene:DHCR7 +2.71, gene:DHCR24 +3.69, gene:SCD +4.17), alongside secretory-pathway stress markers (gene:ATF6 +4.04, gene:DDIT3 +2.79, gene:EIF2AK3 +1.51).", "The lipid load generated by this routing raises demand for mitochondrial oxidation and redox buffering: every represented OXPHOS subunit is up (33/33; gene:NDUFA5 +7.34, gene:ATP5ME +5.20, gene:UQCRC2 +4.02, gene:COX7A2 +3.36) with beta-oxidation and antioxidant transcripts (gene:HADHA +2.86, gene:PRDX3 +3.49, gene:GPX4 +2.79, gene:NNT +2.88), while glycolytic entry transcripts are mixed (gene:HK2 -3.67, gene:SLC2A1 +2.37).", "Net predicted phenotype in the measured mock condition: an APOE4 microglial state with larger acidic/lipid-storage compartment and higher oxidative machinery that is compatible with normal or even increased basal handling of lipid, but with less unused reserve; a shortfall in degradation or oxidation should appear only after an added lipid/debris challenge, and is not asserted here."], "assumptions": ["The supplied RNA rows are a pre-selected differential-expression list (2212 rows, all adjusted p \u003c 0.05 and |effect| \u003e 1, 77% positive); program coherence was judged against that 77% up-biased background, and genes absent from the list are unknown, not unchanged.", "The RNA effect unit is 'reported log fold change' with unspecified logarithm base and is preserved as such; protein spots are log2 fold change on a different platform, so magnitudes are not comparable across modalities.", "Transcript abundance is used as a proxy for machinery capacity only. Lysosomal acidification, cathepsin activity, cholesterol pool distribution (lysosomal vs ER-accessible), lipid-droplet content, phagocytic uptake rate and oxygen-consumption flux were not measured in the supplied data; routing, flux, localization and causal direction are inferred.", "Protein spots are ambiguous multi-candidate 2D-gel features; no spot is treated as identifying a single protein, and keratin/actin candidates are treated as frequent non-specific assignments.", "Pathway members were chosen from canonical lists written before inspecting effect signs, and negative members were retained; co-regulated genes are not independent, so the sign counts are descriptive, not a formal enrichment test.", "Signal is attributed to microglia although the cultures contain astrocytes; a shift in microglial state versus a shift in culture composition cannot be separated here.", "The proposed reduced reserve is a challenge-revealed property; in the supplied mock condition only the state difference is asserted."], "falsifiable_predictions": ["Prospective sterol-pool imaging in mock APOE4 vs APOE3 microglia (filipin or lysosome-targeted probe plus an ER-accessible-cholesterol probe such as ALOD4/D4H, with LysoTracker volume normalized to cell volume): APOE4 should show a larger acidic compartment and a higher lysosomal/ER-accessible cholesterol ratio. If ER-accessible cholesterol is equal or higher in APOE4 while SREBP-target transcripts remain elevated, the routing step is falsified and a direct transcriptional (e.g., SREBF1-driven lipogenic) explanation is favored.", "Prospective sterol-clamp test: acute cholesterol/25-hydroxycholesterol loading should suppress SREBP targets (LDLR, DHCR24, SCD, HMGCS1) less efficiently in APOE4 than APOE3; equal suppression would weaken the claim that ER sensing is mis-informed rather than simply reset.", "Prospective challenge test of reserve versus ongoing defect: after myelin-debris or oxLDL loading, APOE4 should show a smaller incremental rise in fatty-acid-dependent oxygen consumption and greater neutral-lipid/cholesteryl-ester accumulation than APOE3, while basal mock oxygen consumption is equal or higher in APOE4. If APOE4 matches or exceeds APOE3 in incremental oxidation and clears the load equally, the state is successful adaptation with intact reserve and the mechanism's functional consequence is falsified.", "Prospective dependency test: TFEB knockdown or v-ATPase inhibition should collapse the coordinate hydrolase/v-ATPase transcript induction and disproportionately increase lipid accumulation in APOE4; if the induction is TFEB-independent, mechanism step 2 is wrong.", "Prospective spot-resolution test: immunoblot of the spot 043-046 series should show which candidate carries the increase; ANXA1 protein increase would be consistent with the RNA (gene:ANXA1 +4.15), whereas a TALDO1 protein increase would contradict gene:TALDO1 (-2.32) and warn that RNA-protein direction is unreliable in this dataset.", "Prospective negative prediction for the assigned focus: bead/zymosan phagocytic index and F-actin cup formation should not differ substantially between mock APOE4 and APOE3; a clear phagocytic-uptake deficit would favor a receptor/cytoskeletal mechanism over the lipid-routing mechanism."]}, "score": {"hypothesis_id": "hyp_199", "cosine_similarity": 0.516824286118736, "centered_cosine_similarity": 0.26813201430637273, "direction_accuracy": 0.5566343042071198, "balanced_direction_accuracy": 0.3356164383561644, "mean_absolute_error": 0.5018155339805825, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.516824286118736, "centered_cosine_similarity": 0.26813201430637273, "direction_accuracy": 0.5566343042071198, "balanced_direction_accuracy": 0.3356164383561644, "mean_absolute_error": 0.5018155339805825}}}, "cost_usd": 1.74497075, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 2, "global_rank": 4}, {"id": "opus-evidence-v2-b03-hyp_038", "cohort": "opus-evidence-v2", "batch": 3, "hypothesis": {"hypothesis_id": "hyp_038", "title": "APOE4 microglia sit in a TFEB/MITF-coupled endolysosomal-expansion state with simultaneous SREBP sterol-replenishment, indicating lipid routed into and retained within the degradative compartment rather than a sphingolipid-specific defect", "claim": "Under mock treatment, isogenic APOE4 iPSC-derived microglia (co-cultured with astrocytes, day 30) differ from APOE3 mainly by a coordinated cell-state change in which lipid cargo is preferentially routed into an expanded lysosomal compartment: a CLEAR-type transcriptional program (TFEB, MITF, all represented v-ATPase subunits, and a broad hydrolase set that includes the glycosphingolipid enzymes GBA, HEXA/HEXB, GLA, GM2A, SMPD1) is elevated at the same time as an ER sterol-insufficiency program (SREBF1/2 and their downstream synthesis genes, LDLR, SCARB1) and oxysterol/LXR-type genes (CH25H, MYLIP, APOE). The concurrence of catabolic expansion with an unquenched sterol-synthesis-and-uptake program is best explained by mis-compartmentalised lipid (present in endolysosomes, under-represented in the ER regulatory pool) rather than by uniform lipid excess, uniform lipid deficit, or a sphingolipid-pathway-specific bottleneck; degradative and sterol-egress flux were not measured, so the state is a routing/sensing mismatch of unknown functional cost in the unchallenged condition.", "mechanism_steps": ["APOE4 alters the lipoprotein/lipid ligands that microglia internalise and the efficiency with which internalised sterol and glycosphingolipid are handed off from the endolysosome, increasing the fraction of lipid cargo that dwells in the degradative compartment (inferred routing, not measured flux).", "Endolysosomal lipid dwell activates a CLEAR-type transcriptional response: TFEB (gene:TFEB +2.38) and MITF (gene:MITF +1.03) transcripts rise together with every represented v-ATPase subunit (gene:ATP6V1H +6.88, gene:ATP6V1A +4.23, gene:ATP6V0C +3.51, gene:ATP6AP1 +2.30) and with luminal hydrolases (gene:GAA +9.96, gene:CTSK +7.36, gene:NAGLU +5.91, gene:CTSB +5.52, gene:CTSD +2.86), expanding degradative machinery at the transcript level.", "Within that program the glycosphingolipid/sphingolipid catabolic arm is induced in proportion to the rest of the lysosome, not selectively (gene:GBA +6.71, gene:HEXA +5.68, gene:SMPD1 +5.63, gene:HEXB +2.17, gene:GM2A +2.01, gene:GLA +1.53, gene:NPC2 +1.17, gene:GLTP +2.38), together with modest anabolic and disposal steps (gene:CERS4 +2.52, gene:ST3GAL5 +2.17, gene:CERS6 +1.06, gene:KDSR +1.27, gene:SGPL1 +1.09); this argues the sphingolipid changes are a downstream branch of the lysosomal state, not its cause.", "Because sterol delivered into this compartment is under-represented at the ER sensor, SREBP-dependent synthesis and uptake genes stay on (gene:SREBF1 +4.67, gene:SREBF2 +1.06, gene:DHCR24 +3.69, gene:DHCR7 +2.71, gene:LSS +2.27, gene:HMGCS1 +1.08, gene:EBP +1.34, gene:INSIG1 +1.87, gene:LDLR +1.50, gene:SCARB1 +8.22, gene:CD36 +1.38) while oxysterol/LXR-responsive genes also rise (gene:CH25H +1.62, gene:MYLIP +1.28, gene:APOE +1.24); simultaneous SREBP and LXR-type output is the signature of compartment-split sterol rather than of a single global sterol level.", "Newly acquired lipid is buffered into esterified/neutral-lipid and membrane pools instead of being exported (gene:SOAT1 +1.25, gene:DGAT1 +1.72, gene:SCD +4.17, gene:MGLL +4.00), while transcripts for exocytic/late-secretory routing steps are among the comparatively rare decreases (gene:RAB27A -2.52, gene:VTA1 -3.88, gene:STX17 -2.06, gene:M6PR -1.72, gene:GOLPH3L -7.44, gene:GCC1 -5.00), biasing the cell toward intracellular retention over disposal.", "Sustaining lysosomal acidification and lipid remodelling raises transcripts for oxidative ATP production and anaplerosis (gene:MDH1 +8.70, gene:OGDH +8.60, gene:MPC2 +8.02, gene:NDUFA5 +7.31, gene:ATP5ME +5.20, gene:SDHB +1.65), so the state is energetically supported and can be maintained in mock; a lipid-clearance deficit is therefore predicted to be revealed mainly by an added lipid load, not necessarily present as an ongoing defect here."], "assumptions": ["The 2212 RNA rows are a thresholded differential-expression selection (all |effect|\u003e1, all adjusted p\u003c0.05, 77.1% positive) in an unspecified log base; program directions were judged against that 77/23 positive background, and absent genes (e.g. ASAH1, PSAP, UGCG, NPC1, ABCA1, LIPA, GRN, HMGCR, SQLE) are unknown rather than unchanged.", "Transcript increases are assumed to indicate an active TFEB/MITF- and SREBP-driven transcriptional state, not measured enzyme activity, lysosomal pH, protein abundance, sterol pools or lipid flux; TFEB/SREBP nuclear localisation and processing were not measured.", "Protein spots carry 2-6 candidate identities each and are dominated by keratins and actins; they are used only for compatibility testing, and no spot is treated as identification of a single protein.", "Astrocyte co-culture means some lipid ligands are non-cell-autonomous; the comparison is isogenic APOE4 vs APOE3, so genotype-linked lipoprotein handling, not culture composition, is assumed to drive the difference.", "Genes within a program are co-regulated and not independent, so the descriptive coherence reported here is not a formal enrichment result and causality is not established.", "Any clearance deficit is assumed to be latent in mock and to require an added lipid/myelin challenge to become rate-limiting; reduced reserve is not claimed as an ongoing defect in the measured condition."], "falsifiable_predictions": ["Prospective discriminating perturbation: acutely mobilising lysosomal cholesterol in mock APOE4 microglia with 2-hydroxypropyl-beta-cyclodextrin (or by NPC1/NPC2 overexpression) should selectively quench the SREBP arm in APOE4 (SREBF2 targets HMGCS1, LSS, DHCR7, DHCR24, LDLR falling toward APOE3 levels) and reduce CLEAR transcripts (TFEB targets, v-ATPase subunits, GBA/HEXA), with little effect in APOE3; if the SREBP program in APOE4 remains elevated after lysosomal sterol is mobilised, the routing/sensing-mismatch mechanism is weakened and a demand-driven membrane-biosynthetic growth state becomes the better explanation.", "Prospective imaging/biochemistry in the same mock condition: APOE4 should show greater LAMP1 volume per cell with increased filipin-detectable and LysoTracker-positive lysosomal cholesterol and increased lysosomal glycosphingolipid (GM2/GlcCer) despite higher GBA/HEXA transcripts, while cytosolic/ER accessible sterol is not increased; equal lysosomal lipid content and equal LAMP1 volume between genotypes would falsify step 1-2.", "Prospective challenge test of latent capacity: after a myelin-debris or ApoE-lipoprotein load, APOE4 should clear labelled lipid more slowly than APOE3 and accumulate more neutral lipid, even though hydrolase transcripts are higher; equal or faster clearance would mean the expanded lysosomal program is successful adaptation/increased throughput rather than a routing mismatch, and would refute the retention interpretation.", "Prospective causal test of the transcriptional driver: TFEB knockdown or degradation in APOE4 microglia should lower the hydrolase and v-ATPase transcripts (GBA, HEXA, CTSB, ATP6V1A) without normalising SREBP targets, whereas SREBP-2 inhibition should lower the sterol-synthesis arm without collapsing the hydrolase arm; if either manipulation moves both arms in parallel, the two programs are one linear cascade and the compartment-split-sterol claim is weakened.", "Prospective protein-level test resolving current spot ambiguity: targeted immunoblot or targeted MS for GBA, HEXB, CTSD and ATP6V1E1 should show increased protein in APOE4, consistent with the transcript program; if these proteins are unchanged or reduced (as the mixed, multi-candidate spots protein_spot:067, protein_spot:058, protein_spot:069, protein_spot:064 and protein_spot:065 permit), then the lysosomal program is not realised at the protein level and the mechanism must be reframed as a transcript-only response with post-transcriptional limitation.", "Sphingolipid-focus falsifier: if measured GBA, HEXA/HEXB and acid sphingomyelinase activities per cell scale with their transcripts and cellular glycosphingolipid and ceramide levels are equal to or lower than APOE3, then the sphingolipid arm is successful adaptation and must not be described as compensating for retained substrate."]}, "score": {"hypothesis_id": "hyp_038", "cosine_similarity": 0.5119658750128442, "centered_cosine_similarity": 0.2914215004052524, "direction_accuracy": 0.42718446601941745, "balanced_direction_accuracy": 0.2657940405420374, "mean_absolute_error": 0.5423721682847896, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.5119658750128442, "centered_cosine_similarity": 0.2914215004052524, "direction_accuracy": 0.42718446601941745, "balanced_direction_accuracy": 0.2657940405420374, "mean_absolute_error": 0.5423721682847896}}}, "cost_usd": 2.257453, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 3, "global_rank": 5}, {"id": "opus-evidence-v2-b03-hyp_129", "cohort": "opus-evidence-v2", "batch": 3, "hypothesis": {"hypothesis_id": "hyp_129", "title": "APOE4 microglia occupy an anchored lipid-uptake/endolysosomal-processing state in which cargo-derived sterol bypasses the ER sensing pool and sustains SREBP-driven synthesis", "claim": "Under mock conditions, isogenic APOE4 iPSC-microglia differ from APOE3 not by a single failed step but by a coordinated cell-state change: transcripts for scavenger/phagocytic uptake receptors, endosomal traffic and TFEB-associated lysosomal hydrolase/v-ATPase machinery are coherently higher (29/30 and 29/31 represented members positive against a 77%-positive selected-list background), while SREBP-target sterol/fatty-acid synthesis and esterification transcripts stay high, indicating that lipid cargo is routed toward lysosomal catabolism and esterified storage rather than to the ER regulatory sterol pool; the actin system is simultaneously reconfigured from a Rac2/DOCK8/myosin-II motility module (0/11 represented members positive) toward RhoGDI-restrained, integrin- and Arp2/3-based internalisation. This is proposed as ongoing high-throughput lipid handling with reduced motile-surveillance reserve, not as an established degradative bottleneck; no uptake, degradation, sterol or motility flux was measured, so causal direction is not established.", "mechanism_steps": ["APOE4 raises expression of lipoprotein/debris uptake and adhesion receptors (gene:SCARB1 +8.2, gene:ITGA6 +15.5, gene:ITGB1 +6.3, gene:CD36, gene:MRC1, gene:MERTK, gene:GAS6, gene:TREM2, gene:C1QA/B/C, gene:LGALS3), which is expected to increase receptor-mediated delivery of lipid-rich cargo into the endocytic route (delivery rate inferred, not measured).", "Endosomal maturation and lysosomal biogenesis transcripts rise in parallel (gene:DNM2, gene:CLTB, gene:RAB7A, gene:SNX3, gene:VPS26A, gene:CHMP4B, gene:PIK3C3; gene:TFEB +2.4, gene:MITF; hydrolases gene:GAA, gene:GBA, gene:HEXA, gene:HEXB, gene:SMPD1, gene:CTSB, gene:CTSD, gene:CTSK; v-ATPase gene:ATP6V1H, gene:ATP6V1A, gene:ATP6V0C), expanding acidified degradative capacity to match the increased cargo load.", "Sterol and lipid liberated in that compartment is directed to esterification/storage and membrane lipid synthesis (gene:SOAT1, gene:DGAT1, gene:SCD, gene:ACAT2) rather than into the ER regulatory pool, so ER sterol sensing remains permissive and the SREBP program stays on (gene:SREBF1 +4.7, gene:SREBF2, gene:LDLR, gene:HMGCS1, gene:LSS, gene:DHCR7, gene:DHCR24, gene:EBP, gene:INSIG1) despite elevated uptake machinery.", "This lipid-processing state is supported oxidatively rather than glycolytically: TCA/OXPHOS transcripts are uniformly higher (gene:MDH1, gene:OGDH, gene:MPC2, gene:NDUFA5, gene:ATP5ME, gene:UQCRC2, gene:CYCS; 18/18 positive) while glycolytic/PPP transcripts are split or lower (gene:HK2 -3.7, gene:PFKP -3.1, gene:TALDO1 -2.3, gene:PGD -1.3).", "The same state reconfigures the actin machinery: RhoGDI-1 (gene:ARHGDIA +10.6) rises while the leukocyte Rac/DOCK motility-contractility module falls coherently (gene:RAC2, gene:DOCK8, gene:MYO1F, gene:FAM49B, gene:ARHGAP30, gene:SPN, gene:PLEK, gene:PTPN6, gene:MYH9, gene:ACTB, gene:VASP), whereas Arp2/3 and turnover components remain up (gene:ARPC1B, gene:ARPC4, gene:ARPC5, gene:CFL1, gene:TWF2), predicting anchored, receptor-driven internalisation with reduced Rac-dependent process motility.", "Chronic operation of this state produces the accompanying low-grade stress/priming signature (gene:ATF6 +4.0, gene:DDIT3 +2.8, gene:EIF2AK3 +1.5, gene:LGALS3 +2.4, gene:CXCL8, gene:CCL2, gene:NLRP3, gene:GPNMB) and leaves less spare degradative and motile reserve, a deficit expected to become apparent only under an added phagocytic or lipid challenge, not necessarily in the measured mock condition."], "assumptions": ["The supplied RNA rows are a selected differential list (all |effect|\u003e1, adjusted p\u003c0.05, 77% positive); program coherence is judged against that 77%-positive background, and genes absent from the list are unknown rather than unchanged. The RNA logarithm base is unspecified and is preserved as reported.", "Higher transcript abundance for receptors, hydrolases, v-ATPase subunits and SREBP targets is assumed to translate into a corresponding change in protein and pathway capacity; none of these activities, nor cholesterol esterification, lysosomal pH, uptake rate or motility, was measured here.", "Sustained SREBP-target transcription is interpreted as reporting a low ER regulatory sterol pool; this inference would fail if the SREBP targets are driven in APOE4 by an SREBP-independent input.", "Protein spots are treated as ambiguous mixtures (2-6 candidates each; KRT1 in 33, ACTB in 25 spots) and are used only for compatibility, never as identification of a single protein; the spot platform is itself positive-skewed (64/92 up, median +0.485), so positive spots carry little directional weight.", "Astrocyte co-culture, mock treatment and day-30 differentiation are assumed comparable between genotypes, so the differences reflect the isogenic APOE4/APOE3 contrast rather than differentiation-stage drift.", "Reduced motile/degradative reserve is an expectation for a future challenge; the measured mock condition is interpreted as an ongoing adaptive lipid-handling state, and no causal direction has been established by these data."], "falsifiable_predictions": ["Prospective sterol-routing test: acute loading with LDL or cholesterol/methyl-beta-cyclodextrin should suppress SREBP targets (HMGCS1, LDLR, DHCR7, SREBF2) less in APOE4 than in APOE3 microglia, and free/esterified cholesterol partitioning (filipin plus CE mass) should shift toward esters and LAMP1-positive compartments in APOE4. Equal SREBP suppression and equal CE/free-sterol partitioning would weaken the routing step.", "Prospective flux test distinguishing adaptation from bottleneck: pulse-chase of fluorescent myelin or DiI-AcLDL should show equal or greater initial internalisation and equal or faster early cargo degradation (DQ-BSA/quenched-lipid dequenching) per cell in APOE4 under mock conditions, with divergence (cargo accumulation, undigested lipid) appearing only after repeated or high-dose challenge. If APOE4 shows reduced internalisation and slower degradation already at baseline, the adaptation reading is wrong and the degradative-bottleneck alternative is favoured.", "Prospective perturbation ordering test: knockdown of ARHGDIA in APOE4 microglia should restore Rac1-GTP levels, lamellipodial spreading and process motility without normalising the lysosomal (TFEB target) or SREBP target transcripts; conversely, TFEB knockdown should blunt the hydrolase/v-ATPase program and precipitate lipid accumulation selectively in APOE4 under myelin load without restoring motility. If ARHGDIA knockdown also normalises the lysosomal/SREBP programs, the actin change is upstream and the proposed ordering is falsified.", "Prospective esterification test: SOAT1 inhibition (e.g. avasimibe) should lower cholesteryl-ester storage and reduce SREBP-target transcripts toward APOE3 levels preferentially in APOE4; unchanged SREBP targets under effective SOAT1 inhibition would weaken the storage-diversion step.", "Prospective protein-level check that avoids spot ambiguity: targeted immunoblot or MS quantification in the same cultures should show higher LAMP1, ATP6V1A, CTSB/CTSD and SCARB1 protein and lower RAC2/MYO1F protein in APOE4; if lysosomal proteins are unchanged or lower while their transcripts are up, the expanded-capacity step is not supported and a translational or degradative failure model should replace it."]}, "score": {"hypothesis_id": "hyp_129", "cosine_similarity": 0.5079911735522403, "centered_cosine_similarity": 0.2655396190417247, "direction_accuracy": 0.5372168284789643, "balanced_direction_accuracy": 0.3238747553816047, "mean_absolute_error": 0.5068220064724919, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.5079911735522403, "centered_cosine_similarity": 0.2655396190417247, "direction_accuracy": 0.5372168284789643, "balanced_direction_accuracy": 0.3238747553816047, "mean_absolute_error": 0.5068220064724919}}}, "cost_usd": 1.892724, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 4, "global_rank": 6}, {"id": "opus-evidence-v2-b01-hyp_001", "cohort": "opus-evidence-v2", "batch": 1, "hypothesis": {"hypothesis_id": "hyp_001", "title": "APOE4 microglia route sterol into lysosomal and esterified stores, keeping the ER-accessible pool low and locking in a TFEB/SREBP lipid-handling state", "claim": "Under mock conditions, isogenic APOE4 iPSC-microglia differ from APOE3 mainly by an altered lipid-routing cell state: transcripts for lipid uptake (gene:SCARB1 +8.22, gene:CD36, gene:TREM2, gene:MERTK, gene:C1QA/B/C), for sterol esterification/storage (gene:SOAT1, gene:DGAT1, gene:FABP5, gene:CIDEB) and for endolysosomal biogenesis (gene:TFEB +2.38 with 23/25 represented lysosomal genes up, median +2.02) rise together with a complete SREBP-target biosynthetic set (11/11 up: gene:SREBF2, gene:SREBF1, gene:LDLR, gene:HMGCS1, gene:LSS, gene:DHCR7, gene:DHCR24, gene:EBP, gene:ACAT2, gene:INSIG1, gene:SCD). Continued sterol-synthesis and uptake signalling in the presence of expanded catabolic and storage machinery is best explained by an ER-accessible (regulatory) cholesterol pool that remains low while lipid is held in lysosomes and cholesteryl-ester/droplet stores, rather than by a simple increase in successful lipid throughput. All quantities cited are measured abundances; routing, flux and pool sizes are inferred and unmeasured here.", "mechanism_steps": ["APOE4 alters extracellular/intracellular lipoprotein handling in these microglia (gene:APOE +1.24 is measured; particle composition and transfer activity are not measured), so internalised lipid is delivered to the endolysosome in a form that is exported to the ER less efficiently than in APOE3.", "Uptake and opsonic-recognition transcripts are elevated (gene:SCARB1 +8.22, gene:CD36 +1.38, gene:TREM2 +1.28, gene:MERTK +1.30, gene:GAS6, gene:C1QA/gene:C1QB/gene:C1QC, gene:ABCA7), consistent with an increased lipid load entering that compartment.", "The ER-accessible sterol sensor therefore reports insufficiency: the represented SREBP-target program is uniformly up (gene:SREBF2, gene:SREBF1, gene:LDLR, gene:HMGCS1, gene:LSS, gene:DHCR7, gene:DHCR24, gene:EBP, gene:ACAT2, gene:INSIG1, gene:SCD), while oxysterol/LXR-type outputs are also up (gene:CH25H +1.62, gene:CYP27A1 +1.49, gene:MYLIP +1.28) \u2014 a compartment-discordant signature rather than uniform sterol excess or deficit.", "Sterol and fatty acid that do reach the ER are re-esterified and stored instead of returning to the regulatory pool (gene:SOAT1 +1.25, gene:DGAT1 +1.72, gene:FABP5, gene:FABP3, gene:CIDEB, gene:MGLL, with membrane-lipid genes gene:LPCAT1 +3.07, gene:CHPT1 +2.91, gene:PCYT2), sustaining the low ER-accessible pool.", "The retained luminal load accompanies a TFEB/CLEAR-type expansion of the endolysosome: gene:TFEB +2.38, gene:MITF, hydrolases gene:GAA +10.0, gene:CTSK +7.36, gene:GBA +6.71, gene:HEXA, gene:HEXB, gene:SMPD1, gene:CTSB, gene:CTSD, gene:DPP7, gene:MAN2B1, gene:GLA, gene:SGSH, v-ATPase gene:ATP6V1A/gene:ATP6V1H/gene:ATP6V1E1/gene:ATP6V0D1/gene:ATP6AP1, membrane/trafficking gene:LAMP1, gene:SCARB2, gene:IGF2R, gene:RAB7A, gene:SNX3, gene:VPS26A, gene:SLC38A7. Protein spots do not show matching hydrolase increases (lysosome-candidate spots median +0.14; protein_spot:058 -0.85, protein_spot:069 -1.38 and protein_spot:067 -1.00 contain CTSD/CTSB/HEXB among other candidates; protein_spot:064 -1.20 and protein_spot:065 -0.93 contain ATP6V1E1), so expanded transcript-level capacity is not confirmed at the protein level.", "The net state is a DAM-like, lipid-storing microglial phenotype (gene:GPNMB, gene:ITGAX, gene:CLEC7A, gene:FTH1, gene:IGF1, gene:TIMP2 all up; homeostatic markers only weakly changed, gene:TGFBR1 -2.19, gene:CSF1 -5.91) with modest inflammatory output (gene:CXCL8 +3.11, gene:CCL2, gene:NLRP3, gene:IL18) and no coherent UPR or interferon program, predicting a lipidomic shift toward cholesteryl esters, neutral-lipid droplets and lysosomal sphingolipid substrates in APOE4."], "assumptions": ["RNA rows are a pre-selected differential list (all adj. p \u003c 0.05, 77% positive, median +1.46); program directionality is judged against that skewed background, and genes absent from the file (ABCA1, ABCG1, NPC1, LIPA, PLIN2, HMGCR, SQLE) are unknown, not unchanged. The RNA logarithm base is unspecified, so magnitudes are ordinal.", "Coordinated transcript changes in the SREBP-target and CLEAR-target sets are used as read-outs of upstream sterol sensing and TFEB-type activity; neither SREBP2 cleavage, TFEB nuclear localisation, nor hydrolase activity was measured, so activity and flux remain inferred.", "2D-gel spots carry 2-6 candidate identities each (mean 4.8) and are used only for compatibility, never as confirmation of a named protein; the strongly increased series protein_spot:043-047 is equally consistent with ANXA1 (gene:ANXA1 +4.15) or TALDO1 (gene:TALDO1 -2.32) or PSMD7/ACTB, and this ambiguity is preserved.", "Effects are attributed to the APOE4/APOE3 genotype difference in an isogenic pair at day 30 under mock treatment; astrocyte co-culture, cell-composition drift and any dissociation artefact are assumed not to generate the specific lysosome/sterol coherence.", "The mechanism claims an ongoing routing bias in the measured mock condition; any additional fragility (e.g. under lipid or myelin challenge) is a future-challenge prediction, not something these data establish.", "Descriptive coherence (lysosome 23/25 up, sterol synthesis 11/11 up) is not a formal enrichment result; the genes are not independent and no pathway test corrected for the selection."], "falsifiable_predictions": ["Prospective, discriminating: in mock APOE4 vs APOE3 microglia, quantify the ER/PM-accessible cholesterol pool (ALOD4 or PFO-D4 probe) together with lysosomal unesterified cholesterol (filipin) and cholesteryl-ester/neutral-lipid mass (LC-MS, BODIPY). The mechanism predicts APOE4 shows lower accessible cholesterol with higher lysosomal and esterified sterol. If APOE4 instead shows equal or higher accessible cholesterol and unchanged cholesteryl esters, the routing mechanism is falsified and the 'successful high-throughput anabolic state' alternative is favoured.", "Prospective: acute relief of the routing block (2-hydroxypropyl-beta-cyclodextrin, or SOAT1 inhibition with avasimibe) should, within hours and without changing genotype, normalise the SREBP-target transcripts (gene:LDLR, gene:HMGCS1, gene:DHCR7, gene:DHCR24) and reduce droplet content selectively in APOE4. Persistence of the sterol-synthesis signature after the ER pool is restored would weaken the mechanism.", "Prospective: per-lysosome degradative flux (DQ-BSA or BODIPY-LDL/myelin degradation normalised to LAMP1 area) should be equal or lower in APOE4 despite the higher hydrolase transcripts, i.e. capacity does not scale with load. A clearly higher per-lysosome flux in APOE4 would refute the 'expanded but not sufficient' component while leaving the storage phenotype to be explained.", "Prospective: TFEB knockdown should preferentially reduce hydrolase and v-ATPase transcripts (gene:GAA, gene:CTSK, gene:GBA, gene:ATP6V1A) in APOE4 and further increase droplet/cholesteryl-ester load; if lysosomal transcripts fall but lipid storage does not increase, the lysosomal arm is a bystander of a separate activation program rather than a load-driven response.", "Prospective, protein-level test of the unresolved spots: targeted immunoblot/PRM for CTSD, CTSB, ATP6V1E1, ANXA1 and TALDO1 should show ANXA1 increased and mature-CTSD redistributed rather than uniformly increased; TALDO1 protein increasing while gene:TALDO1 is -2.32 would indicate a post-transcriptional layer this mechanism does not describe."]}, "score": {"hypothesis_id": "hyp_001", "cosine_similarity": 0.5045434714896747, "centered_cosine_similarity": 0.27286187193398587, "direction_accuracy": 0.6003236245954693, "balanced_direction_accuracy": 0.44526086474910465, "mean_absolute_error": 0.5448122977346278, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.5045434714896747, "centered_cosine_similarity": 0.27286187193398587, "direction_accuracy": 0.6003236245954693, "balanced_direction_accuracy": 0.44526086474910465, "mean_absolute_error": 0.5448122977346278}}}, "cost_usd": 2.02124275, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 5, "global_rank": 7}, {"id": "opus-original-b09-hyp_066", "cohort": "opus-original", "batch": 9, "hypothesis": {"hypothesis_id": "hyp_066", "title": "APOE4 microglia mount a TFEB-associated lysosomal hydrolase transcript program that is not matched at the protein-spot level, creating a post-transcriptional lysosomal degradative-capacity bottleneck that diverts lipid into esterified storage; type-I interferon signaling is not the differentiator", "claim": "Under mock treatment, isogenic APOE4 iPSC-derived microglia differ from APOE3 primarily by a large, pathway-coherent induction of lysosomal hydrolase and CLEAR-network transcripts (median reported logFC +4.52 for 15 hydrolases versus +1.46 for the whole selected DE list, permutation p\u003c5e-5) that is not accompanied by any coherent increase in the 2D-gel protein spots whose candidate lists contain those hydrolases (mean +0.28 log2, versus +0.35 log2 for all spots, with significant spots in both directions). We hypothesise that the limiting step is post-transcriptional luminal degradative capacity - delivery, maturation and activation of hydrolases inside acidified lysosomes - rather than transcription, so that lipid substrate arriving through an elevated uptake/esterification program (SCARB1, SCD, SREBF1, SOAT1, DGAT1, ABCA7) is retained and shunted into esterified lipid storage. The interferon focus is rejected: no canonical type-I interferon-stimulated gene appears in the 2212-gene RNA list, and chemokine transcripts are not enriched above the global upward shift (Mann-Whitney p=0.93). Causality is not established by these data.", "mechanism_steps": ["Step 1 (measured RNA, inferred flux): APOE4 microglia show higher transcripts for lipoprotein/lipid uptake and esterification-lipogenesis (gene:SCARB1 +8.22, gene:SCD +4.17, gene:SREBF1 +4.67, gene:ABCA7 +2.14, gene:DGAT1 +1.72, gene:SOAT1 +1.25, gene:CD36 +1.38, gene:COLEC12 +1.53). We infer, but did not measure, an increased flux of lipid/lipoprotein substrate delivered to the endolysosomal system.", "Step 2 (measured RNA): a TFEB/TFEC-associated CLEAR-like transcriptional program is elevated (gene:TFEB +2.38, gene:TFEC +1.65, gene:LAMP1 +1.38, gene:ATP6V1A +4.23) together with 14 of 15 detected lysosomal hydrolases (gene:GAA +9.96, gene:CTSK +7.36, gene:GBA +6.71, gene:NAGLU +5.91, gene:HEXA +5.68, gene:SMPD1 +5.63, gene:CTSB +5.52, gene:DPP7 +4.52, gene:CTSD +2.86, gene:HEXB +2.17). We interpret this as a compensatory transcriptional response to lysosomal substrate load, not as evidence of increased degradation.", "Step 3 (primary bottleneck; inferred): mature, catalytically competent luminal hydrolase content and degradative flux do not scale with the transcript induction. The only protein-level evidence available - 2D-gel spots whose ambiguous candidate lists include cathepsins and hexosaminidase - shifts bidirectionally and shows no net increase (protein_spot:052 +2.14 and protein_spot:053 +1.54 up, but protein_spot:067 -1.00, protein_spot:069 -1.38 and protein_spot:058 -0.85 down; set mean +0.28 log2 versus +0.35 for all spots). Spot identity is not unique, so this is suggestive, not proof.", "Step 4 (inferred consequence): undegraded lipid and glycolipid substrate is retained in LAMP1-positive compartments. Transcripts associated with lysosomal stress, storage and glycan/lipid-damage sensing are elevated (gene:LGALS3 +2.37, gene:GPNMB +1.11, gene:CTSD +2.86, gene:GBA +6.71). Lipid amount, lysosomal pH and lysosomal lipid localisation were not measured here.", "Step 5 (measured RNA, coherent with sterol-replete ER): retained sterol is esterified and stored rather than resynthesised - the SREBP-2 sterol-synthesis arm is at or below the global shift (gene:HMGCS1 +1.08, gene:SREBF2 +1.06, gene:LDLR +1.50, gene:INSIG1 +1.87; set Mann-Whitney p=0.65) while the SREBP-1/desaturation arm and esterification enzymes are high (gene:SREBF1, gene:SCD, gene:DGAT1, gene:SOAT1). This argues against sterol starvation and for a storage-biased, sterol-replete state.", "Step 6 (rejection of the assigned focus): inflammatory output is a weak secondary correlate. Chemokine transcripts (gene:CXCL8 +3.11, gene:CCL2 +2.12, gene:CXCL1 +1.59) are not enriched above the +1.46 background (Mann-Whitney p=0.93), NF-kB core genes are not enriched (p=0.50) and include down-shifted gene:TNFAIP3 (-1.05) and gene:RELB (-1.30), pyroptosis effector gene:GSDMD is down (-3.18), and no canonical type-I interferon-stimulated gene is present in the list. We therefore place inflammation downstream of, not upstream of, the lysosomal-lipid bottleneck."], "assumptions": ["The supplied RNA rows are a selected differential-expression list, not an unbiased transcriptome; the +1.46 median is treated as the correct background for enrichment, and absence of a gene (for example LIPA, NPC1, ABCA1, PLIN2, ISG15, MX1, STAT1) is treated as not measured or not selected, not as unchanged.", "The logarithm base of the RNA effects is unspecified and is preserved as reported; protein spots are log2. RNA and protein effects are therefore never compared on a common numeric scale, only by direction and by rank within their own modality.", "2D-gel protein spots are mixtures with multiple candidate genes; a spot change is treated as evidence about a spot, not about a uniquely identified protein. The inference in step 3 assumes that if mature cathepsin content had risen several-fold, at least the cathepsin-candidate spots would have risen coherently.", "Transcript abundance is assumed to be an imperfect proxy for enzyme amount and no proxy at all for enzyme activity, lysosomal pH, lipid content or subcellular localisation, none of which were measured.", "The strong global upward RNA shift (77% positive, all |logFC|\u003e1) is assumed to include a composition or normalisation component; only relative enrichment against that shift is interpreted.", "Astrocyte co-culture is assumed not to differ systematically between the APOE3 and APOE4 arms; if it does, some transcript differences are non-cell-autonomous.", "Very large single-gene logFC values are assumed to be less reliable than moderate ones, since effect size and adjusted p-value are essentially uncorrelated in this list (Spearman -0.03)."], "falsifiable_predictions": ["Discriminating perturbation: in mock APOE4 versus APOE3 microglia, per-LAMP1-volume lysosomal degradative activity (Magic Red cathepsin B, BODIPY-FL-pepstatin A for mature cathepsin D, DQ-BSA dequenching) will be equal to or lower in APOE4 despite at least 4-fold higher CTSB/CTSD/GBA mRNA, and mature-form cathepsin B/D by western blot will rise far less than transcript. If activity and mature protein rise in proportion to transcript, the post-transcriptional bottleneck is refuted.", "Discriminating perturbation: raising CLEAR transcription further (TFEB overexpression or torin-1) will not normalise neutral-lipid or unesterified-cholesterol load in LAMP1-positive compartments of APOE4 cells, whereas directly restoring luminal capacity (acidifying nanoparticles, or recombinant GBA/cathepsin delivery) will reduce it without lowering hydrolase mRNA. Full rescue by TFEB overexpression would show transcription, not capacity, is limiting and would refute the chosen bottleneck.", "Substrate-source test: SCARB1 knockdown or blocking antibody in APOE4 microglia will lower BODIPY and filipin signal in LAMP1-positive compartments and secondarily reduce the hydrolase transcript induction (CTSB, GBA, HEXA) toward APOE3 levels. Unchanged CLEAR induction after SCARB1 loss would refute step 1 as the substrate source.", "Storage-versus-synthesis test: APOE4 cells will contain more cholesteryl ester and triacylglycerol per cell than APOE3 while incorporating no more labelled acetate into free sterol; SOAT1 inhibition (avasimibe) will shift the excess from ester to free cholesterol and increase lysosomal membrane damage markers rather than normalise total sterol. Increased de novo sterol synthesis flux in APOE4 would contradict step 5.", "Interferon falsification of the assigned focus: an ISG panel (ISG15, MX1, IFIT1, OAS1, STAT1, IRF7) by qPCR or targeted proteomics will show no APOE4-over-APOE3 induction, and IFNAR1-blocking antibody or JAK1/2 inhibition will not alter the lysosomal or lipid phenotype. A coherent APOE4 ISG induction, or rescue of the phenotype by IFNAR blockade, would show the absence of ISGs here was a gene-selection artifact and would support the interferon mechanism I rejected.", "Inflammation-is-downstream test: correcting lysosomal capacity (prediction 2) will reduce CXCL8 and CCL2 transcript and secreted protein in APOE4, whereas blocking NF-kB (IKK inhibition) will reduce CXCL8/CCL2 without reducing lysosomal lipid load or hydrolase transcripts. If IKK inhibition also normalises the lysosomal program, inflammation is upstream and step 6 is wrong.", "Identity control: mass-spectrometry re-identification of protein_spot:067, protein_spot:058 and protein_spot:069 will show cathepsin B/D forms among the changing species. If those spots are dominated by actin or keratin, the mRNA-to-protein discordance evidence in step 3 collapses and the bottleneck must be re-argued from activity assays alone."]}, "score": {"hypothesis_id": "hyp_066", "cosine_similarity": 0.50094696006937, "centered_cosine_similarity": 0.21300497052450346, "direction_accuracy": 0.5825242718446602, "balanced_direction_accuracy": 0.3512720156555773, "mean_absolute_error": 0.5325113268608413, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.50094696006937, "centered_cosine_similarity": 0.21300497052450346, "direction_accuracy": 0.5825242718446602, "balanced_direction_accuracy": 0.3512720156555773, "mean_absolute_error": 0.5325113268608413}}}, "cost_usd": 2.009124, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 3, "global_rank": 8}, {"id": "opus-original-b10-hyp_043", "cohort": "opus-original", "batch": 10, "hypothesis": {"hypothesis_id": "hyp_043", "title": "APOE4 microglia run a TFEB/CLEAR-type lysosomal biogenesis transcriptional program that is not matched at the lysosomal protein level, making terminal degradative capacity the bottleneck for endolysosomal cargo processing", "claim": "Under mock conditions, isogenic APOE4 iPSC-derived microglia differ from APOE3 primarily by a coordinated transcriptional up-shift of endosomal sorting and lysosomal hydrolase/v-ATPase genes (including TFEB itself) that is NOT accompanied by a corresponding increase in lysosome-associated protein spots - several of which are among the few significantly decreased spots. We hypothesise that the rate-limiting step in APOE4 microglia is the mature, acidification-competent hydrolase pool inside late endosomes/lysosomes (post-transcriptional degradative capacity), so cargo influx exceeds catabolic throughput and the transcriptional CLEAR response is a compensatory, unresolved feedback rather than evidence of increased degradation. Causality is not established by these data; the RNA rows are preselected differential-expression results and the protein spots are multi-candidate, so all activity, flux and localisation statements below are inferred, not measured.", "mechanism_steps": ["Step 1 (measured RNA, inferred flux): Transcripts for lipoprotein/debris uptake receptors and endocytic machinery are higher in APOE4 (gene:SCARB1 +8.22, gene:DNM2 +5.82, gene:CD36, gene:TREM2, gene:MERTK, gene:ABCA7, gene:APOE). We infer, but did not measure, increased delivery of lipid- and protein-rich cargo into the endosomal system.", "Step 2 (measured RNA, inferred flux): Early-to-late endosome maturation and sorting transcripts are coherently elevated above the study-wide background shift (gene:RAB7A, gene:SNX3, gene:VPS26A, gene:VPS35L, gene:CHMP4B, gene:AP3D1, gene:AP5M1, gene:PIK3C3; set median percentile 0.71, permutation p=0.012), consistent with cargo being routed towards late endosomes.", "Step 3 (measured RNA): A CLEAR/lysosome-biogenesis-like transcriptional program is engaged - gene:TFEB +2.38 together with hydrolases (gene:GAA, gene:GBA, gene:HEXA, gene:CTSB, gene:CTSD, gene:CTSK, gene:SMPD1, gene:NAGLU), v-ATPase subunits (gene:ATP6V1H, gene:ATP6V1A, gene:ATP6V0C, gene:ATP6V1E1), membrane proteins (gene:LAMP1, gene:SCARB2) and the lysosomal amino-acid exporter gene:SLC38A7. TFEB transcript abundance is measured; TFEB nuclear localisation and transcriptional activity are inferred only.", "Step 4 (measured protein spots, inferred pool): The protein-spot layer does not mirror step 3. Spots whose candidate lists contain a lysosomal hydrolase or v-ATPase subunit sit at the background of the spot distribution (median percentile 0.46), and 6 of the 9 significantly decreased spots carry such a candidate (protein_spot:058, protein_spot:067, protein_spot:069 with cathepsin/HEXB candidates; protein_spot:064 and protein_spot:065 with ATP6V1E1; protein_spot:086 with ACP2), versus 12 of 38 increased spots (Fisher two-sided p=0.068, nominal, post hoc set). We therefore infer that the functional mature-hydrolase and V1-sector protein pool is not expanded in proportion to its mRNA; this pool was not directly measured.", "Step 5 (inferred bottleneck): Because per-lysosome degradative capacity (hydrolase activity x luminal acidification) does not scale with the increased cargo flux of steps 1-2, undegraded lipid and protein cargo is predicted to accumulate in late endosomes/lysosomes in APOE4. No lipid, pH, or degradation-flux measurement is supplied, so this step is a prediction, not an observation.", "Step 6 (measured RNA, inferred feedback): Persistent undegraded substrate is proposed to sustain the CLEAR program (step 3) and to bias lipid handling and secretion (gene:SREBF1 +4.67, gene:SCD +4.17, gene:DHCR24, gene:SOAT1, gene:APOE) with a modest chemokine component (gene:CXCL8, gene:CCL2). Loss of the dominant microglial endosomal protease transcript gene:CTSS (-5.57) and gene:IDS, gene:LAPTM5, gene:VTA1 indicates the program is selective, not a uniform lysosomal induction, and further narrows specific catabolic branches."], "assumptions": ["The RNA rows are preselected differential-expression results (all |effect| \u003e= 1.00) with a strong global positive offset (77.1% up, median +1.46 in an unspecified log base); pathway claims therefore rest on rank within this selected set, not on absolute fold change, and the logarithm base is left unspecified as supplied.", "Protein spots are not uniquely identified proteins (3-6 candidate genes each); assigning protein_spot:058/067/069 to cathepsins/HEXB and protein_spot:064/065 to ATP6V1E1 is an assumption. ANXA1 is a shared candidate of spots 064 and 065, but seven other ANXA1-containing spots are increased, which is why ATP6V1E1 is favoured as the shared explanation - this remains unproven.", "RNA and protein were measured on different scales and normalisations; the RNA-protein discordance is assessed relative to each modality's own background, not by direct ratio.", "Transcript abundance is assumed to be at least partly indicative of the corresponding protein synthesis demand; TFEB activity, lysosomal pH, hydrolase maturation state, cargo load, autophagic flux and lipid content were not measured (unverified background knowledge is used only to name pathway membership).", "No replicate number, dispersion, or batch information is supplied, so the very large fold changes (up to +15.5) may include low-count or technical inflation.", "The gene sets used were curated by hand from background knowledge after inspecting the data; their nominal permutation and Fisher p-values are not corrected for multiple set testing."], "falsifiable_predictions": ["Discriminating perturbation: acute v-ATPase inhibition (bafilomycin A1 or concanamycin A, dose-response) should produce a SMALLER incremental change in lysosomal pH, DQ-BSA dequenching and mature-cathepsin activity in APOE4 than in isogenic APOE3 microglia (occlusion), because APOE4 lysosomes are already close to the acidification/hydrolase-capacity limit. Equal or larger incremental sensitivity in APOE4 would weaken the proposed bottleneck.", "Per-cell mature cathepsin B/D activity and DQ-BSA/DQ-ovalbumin degradation, normalised to LAMP1+ volume, will be LOWER or unchanged in APOE4 despite higher CTSB/CTSD/GBA/HEXA/GAA transcripts; immunoblot should show an increased pro-form:mature-form ratio for CTSD. If mature enzyme and activity rise in proportion to mRNA, the mechanism is falsified.", "Reducing cargo influx (SCARB1/CD36 blockade, lipoprotein-depleted medium, or cytochalasin-D-blocked uptake for 24-48 h) should normalise the CLEAR-type transcripts (TFEB, GBA, HEXA, CTSB, GAA) in APOE4 towards APOE3. If those transcripts stay elevated when cargo influx is blocked, the driver is constitutive upstream TFEB/mTORC1 signalling rather than cargo overload, weakening step 6.", "Restoring terminal capacity without touching transcription - exogenous recombinant hydrolase delivery, cathepsin-D/B overexpression, or v-ATPase-assembly support - should reduce accumulated undegraded cargo (LipidTOX/filipin, Lysotracker volume, LC3-II/p62) in APOE4 more than in APOE3. No genotype-selective rescue would weaken the mechanism.", "Because CTSS transcript is strongly decreased (gene:CTSS -5.57), CTSS-preferred substrate degradation (e.g. invariant-chain/Ii processing, elastin-like peptides) should be selectively impaired in APOE4 even if bulk proteolysis is only mildly reduced; equal CTSS-specific activity across genotypes would indicate the RNA row is not protein-relevant and weaken step 6.", "Blinded 2D-gel or targeted MS re-identification of protein_spot:064 and protein_spot:065 should confirm ATP6V1E1 (not ANXA1) as the decreased species; identification of ANXA1 or another non-lysosomal candidate as the driver would remove the acidification arm of the mechanism."]}, "score": {"hypothesis_id": "hyp_043", "cosine_similarity": 0.4980896621965569, "centered_cosine_similarity": 0.21002699860098925, "direction_accuracy": 0.6229773462783171, "balanced_direction_accuracy": 0.3832108702876343, "mean_absolute_error": 0.5224012944983819, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.4980896621965569, "centered_cosine_similarity": 0.21002699860098925, "direction_accuracy": 0.6229773462783171, "balanced_direction_accuracy": 0.3832108702876343, "mean_absolute_error": 0.5224012944983819}}}, "cost_usd": 1.77884225, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 4, "global_rank": 9}, {"id": "opus-evidence-v2-b05-hyp_009", "cohort": "opus-evidence-v2", "batch": 5, "hypothesis": {"hypothesis_id": "hyp_009", "title": "APOE4 microglia occupy a substrate-driven catabolic state: expanded endolysosomal-hydrolytic and mitochondrial oxidative machinery with lipid re-esterification, at the expense of the actomyosin/Rho motility module", "claim": "Under mock treatment, isogenic APOE4 iPSC-microglia (co-cultured with astrocytes) differ from APOE3 chiefly by a coordinated cell-state change rather than by a single bottleneck: transcripts for lipoprotein/scavenger uptake, endolysosomal routing, lysosomal hydrolases plus v-ATPase, mitochondrial TCA/electron-transport carbon handling, and neutral-lipid esterification are jointly elevated in the top tail of this selected DE list, while the actomyosin/Rho-GTPase motility module carries the most extreme negative effects (with ARHGDIA, an inhibitory Rho-GDI, in the top 0.1% positive). We propose that APOE4 raises the lipid/lipoprotein substrate load routed into microglial lysosomes, and that the cells respond with an MITF/TFEB-associated expansion of degradative and oxidative capacity plus esterified-lipid storage, reallocating away from actin-driven surveillance/motility. This is an expansion-of-capacity/routing-shift state, not a demonstrated degradation failure; only inferred activities, not measured flux, distinguish the two, and causality is not established.", "mechanism_steps": ["STEP 1 (measured transcripts; inferred flux): APOE4 increases lipoprotein/lipid cargo delivered to microglia and cells raise uptake-receptor transcripts - SCARB1 (gene:SCARB1, +8.22, 99th pct of this list), CD36, LDLR, MRC1, COLEC12, STAB1, TREM2, MERTK/GAS6, C1QA/B/C, ANXA1 (+4.15); note most of these sit near the list's median magnitude (~1.1-1.5), so receptor mRNA up-shift is modest relative to the selected background (77% of rows are positive).", "STEP 2 (routing): internalized cargo is directed through an up-shifted endocytic/endosomal module - DNM2 (+5.82), CLTB, AP5M1 (+9.78), AP3D1, ARFGEF1, RAB7A (+2.65), RAB32, SNX3/VPS26A (retromer), CHMP4B, VAMP3, ARL8B, VPS18 - toward late endosomes/lysosomes rather than recycling; AP1M1, SYNJ1, ANKFY1 and M6PR are exceptions in the opposite direction.", "STEP 3 (capacity expansion): a CLEAR-type lysosomal program is coordinately elevated - GAA (+9.96), GBA (+6.71), HEXA (+5.68), CTSB (+5.52), CTSK (+7.36), SMPD1 (+5.63), CTSD, HEXB, GLA, MAN2B1, SGSH, LAMP1, IGF2R, plus v-ATPase subunits ATP6V1A (+4.23), ATP6V0C, ATP6V0D1, ATP6V1C1, ATP6V1F, ATP6V1E1, ATP6AP1/2, with the transcription factors TFEB (+2.38) and MITF (+1.03) also increased (27/29 represented members positive; MW vs list background p=0.023).", "STEP 4 (carbon disposal and storage): lipid-derived carbon is handled by an increased mitochondrial oxidative module - MPC2 (+7.98), OGDH (+8.56), MDH1 (+8.72), GOT1, DLD, ACO2, SDHB, UQCRC2, COX7A2, ATP5F1B, NDUFA5, GLUD1, SLC25A46, HADHA, ACOX1 (15/15 represented members positive, median +4.02, MW vs background p=4.5e-6) - and in parallel is re-esterified/stored via SOAT1, DGAT1, SCD (+4.17), SREBF1 (+4.67), FABP5, GPNMB, LGALS3.", "STEP 5 (reallocation, focus arm): the same state down-shifts actomyosin/Rho-dependent motility and surface remodelling - MYH9 (-6.38), FAM49B/CYRI-B (-5.83), ACTB (-4.98), CORO2A (-3.70), MYO1F (-3.69), VASP (-3.44), RAC2, DOCK8, ARHGDIB, ARHGAP30 (-5.16), RHOQ, SPN, SEMA4A, SELL - while the Rho-GTPase inhibitor ARHGDIA is the third-largest positive effect in the list (+10.61) and branched-actin subunits (ARPC1B/4/5, CFL1, TWF2, ACTN4, FLNA) remain positive; we infer reduced Rho/Rac-dependent motile and large-particle-engulfment activity rather than loss of endocytic machinery.", "STEP 6 (net measured-condition state): APOE4 microglia in mock are therefore predicted to be a less motile, lipid-processing cell with larger/more active lysosomal and oxidative compartments and increased esterified neutral lipid; a degradative or immune deficit is expected to become rate-limiting only under a substrate or activation challenge (CSF1 -5.91, TRAF4 -7.17, CCL4, CCL23, CD69 down indicate a damped autocrine/activation arm), not necessarily in the measured condition."], "assumptions": ["The RNA rows are a pre-selected differential-expression list (all 2212 rows have |effect| \u003e 1 and adjusted p \u003c 0.05, 77.1% positive) in an unspecified log base; program directions were therefore judged against this 77%-positive, median +1.46 background, not against 50/50. Absent genes (e.g., ABCA1, LIPA, PLIN2, NPC1, PSAP, GRN, P2RY12, MCOLN1) are unknown, not unchanged, and one row is unidentified (gene:??).", "Transcript abundance is assumed to track, imperfectly, the abundance of the corresponding hydrolase, v-ATPase, TCA/ETC and cytoskeletal proteins; no hydrolase activity, respiration, uptake rate, lysosomal pH or lipid pool was measured here, so all flux, localization and activity statements are inferred.", "2D-gel protein spots are ambiguous (92 spots, mean 4.8 candidate genes/spot, keratin contaminants frequent, 64 up / 24 down overall). They are used only for compatibility/contradiction: spots 043-047 (up to +3.05) are consistent with increased ANXA1 (gene:ANXA1 +4.15) but equally consistent with TALDO1, whose transcript is down (-2.32); no spot is treated as confirming any single protein.", "Members of each program were fixed from canonical pathway knowledge (unverified background knowledge) before signs were inspected; all queried members are reported with represented/queried counts, and no member was dropped to make directions agree. Genes within a program are co-regulated, so sign counts and rank tests are descriptive coherence, not independent enrichment evidence.", "The astrocyte co-culture and iPSC differentiation state are assumed comparable between genotypes, so the differences reflect the isogenic APOE4/APOE3 contrast rather than differing microglial maturation or cell-composition; a global count-scaling or maturation difference could inflate the shared positive tail, which is why within-list relative contrasts (mito/lysosome in the top tail vs actomyosin/Rho in the bottom tail) carry the argument.", "Damped activation/autocrine transcripts (CSF1, TRAF4, CCL4, CD69) are assumed to indicate reduced reserve that would be revealed by a future stimulus, not an established ongoing functional deficit in the mock condition."], "falsifiable_predictions": ["PROSPECTIVE, primary discriminator (mock condition, no challenge): APOE4 microglia should show, per cell, both greater lysosomal volume/LysoTracker signal and greater hydrolase activity (GBA, HEXA/HEXB, cathepsin B/D substrate assays) and higher basal + maximal oxygen consumption than APOE3, together with increased esterified neutral lipid (BODIPY, cholesteryl-ester and triacylglycerol species). If lysosomal volume and hydrolase transcripts rise but measured hydrolase activity and OCR are unchanged or lower while undegraded substrates (LacCer, glucosylceramide, free cholesterol) accumulate, the 'expanded capacity/adaptive routing' mechanism is falsified in favour of failed compensation for a degradative bottleneck.", "PROSPECTIVE flux test: pulse-chase of labelled lipoprotein/myelin or 13C-oleate should show equal-or-higher internalization AND faster cargo clearance plus higher label appearance in TCA intermediates in APOE4; slower clearance with equal uptake would weaken steps 3-4.", "PROSPECTIVE focus-arm test: live imaging should show reduced process motility/migration and reduced actin-dependent large-particle (bead, synaptosome) engulfment in APOE4 despite unchanged or higher soluble/receptor-mediated endocytic uptake; equal-or-higher migration and equal large-particle engulfment would falsify step 5 and would specifically reject the assigned phagocytic/cytoskeletal framing.", "PROSPECTIVE causal test of the driver: TFEB/MITF knockdown (or mTORC1 activation) in APOE4 microglia should selectively collapse the hydrolase/v-ATPase transcript increase and further raise stored neutral lipid; persistence of the hydrolase/v-ATPase elevation after TFEB/MITF loss would falsify the CLEAR-program step while leaving the substrate-load claim intact.", "PROSPECTIVE routing test: SOAT1 inhibition (avasimibe) should shift APOE4 carbon from cholesteryl esters toward free cholesterol with increased lysosomal stress and cathepsin release markers; no genotype difference in that response would argue the esterification/storage arm is incidental.", "PROSPECTIVE Rho-arm test: constitutive Rac1/RhoA activation or ARHGDIA knockdown should restore APOE4 motility and large-particle engulfment without normalizing lysosomal/mitochondrial transcripts; if it also normalizes the lysosomal-oxidative program, the two arms are not separable and step 5 is not a downstream reallocation."]}, "score": {"hypothesis_id": "hyp_009", "cosine_similarity": 0.4949131875941613, "centered_cosine_similarity": 0.2903942439714954, "direction_accuracy": 0.6051779935275081, "balanced_direction_accuracy": 0.48086437986929065, "mean_absolute_error": 0.5101650485436893, "by_modality": {"lipid_abundance": {"n_features": 618, "cosine_similarity": 0.4949131875941613, "centered_cosine_similarity": 0.2903942439714954, "direction_accuracy": 0.6051779935275081, "balanced_direction_accuracy": 0.48086437986929065, "mean_absolute_error": 0.5101650485436893}}}, "cost_usd": 2.3333225, "duplicate": false, "cosine_defined": true, "centered_cosine_defined": true, "cohort_rank": 6, "global_rank": 10}], "selection": {"top_n": 10, "metric": "cosine_similarity", "evaluated_count": 1432}, "note": "Previously inspected development panel. Scores rank hypothesis-predictor pairs, not causal validity. Astra and Claude use different predictors and harnesses. Ongoing batches are excluded from this fixed snapshot."};
